-- public.break_bars(p_world uuid, p_uid uuid, p_lump text, p_short integer, p_prefer bigint)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.break_bars(p_world uuid, p_uid uuid, p_lump text, p_short integer, p_prefer bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare r record; v_short int := p_short; k int; m metal_def;
begin
  if v_short <= 0 then return; end if;
  select * into m from metal_def where lump = p_lump;
  if m.id is null then return; end if;
  for r in
    select s.id, s.count from craft_stock(p_world, p_uid, p_prefer) s
     where s.def = m.id || '_ingot'
     order by (s.id = p_prefer) desc, s.draw
  loop
    exit when v_short <= 0;
    k := least(r.count, ceil(v_short::numeric / ingot_lumps())::int);
    perform unbar(p_world, p_uid, r.id, k * ingot_lumps());
    v_short := v_short - k * ingot_lumps();
  end loop;
end $function$
